class Solution { public long[] mostFrequentIDs(int[] nums,int[] freq){Map<Integer,Long> frequency=new HashMap<>();PriorityQueue<long[]> heap=new PriorityQueue<>((first,second)->first[0]!=second[0]?Long.compare(second[0],first[0]):Long.compare(second[1],first[1]));long[] answer=new long[nums.length];for(int index=0;index<nums.length;index++){long updated=frequency.getOrDefault(nums[index],0L)+freq[index];frequency.put(nums[index],updated);heap.add(new long[]{updated,nums[index]});while(frequency.get((int)heap.peek()[1])!=heap.peek()[0])heap.poll();answer[index]=heap.peek()[0];}return answer;} }
